-- ============================================================================
-- QC Inspection System — initial PostgreSQL schema
--
-- Conventions
--   • snake_case columns; the API maps them to the camelCase domain model.
--   • UUID primary keys generated by the database (gen_random_uuid, core since
--     PostgreSQL 13 — no extensions required, which keeps Azure Flexible
--     Server setup to zero).
--   • Every evidence table carries deleted_at / deleted_by_id: nothing is ever
--     hard-deleted (§10). A trigger makes DELETE fail at the database, so no
--     bug, script or console session can remove quality evidence.
--   • The audit log is append-only (§11): rows cannot be edited and cannot be
--     deleted; the only permitted change is marking one purged.
--   • Records that can be corrected after their first save carry a version
--     column for optimistic concurrency (§9.4).
--   • numeric (not float) for quantities and measurements — a 2.50 mm reading
--     must stay 2.50, not 2.4999999.
-- ============================================================================

-- ---- Enumerations ----------------------------------------------------------

CREATE TYPE user_role AS ENUM ('inspector', 'supervisor', 'admin');
CREATE TYPE session_status AS ENUM ('Open', 'Closed');
CREATE TYPE shift_letter AS ENUM ('A', 'B', 'C');
CREATE TYPE dimension_status AS ENUM ('Pass', 'Fail', 'Warning', 'Pending');
CREATE TYPE dimension_source AS ENUM ('item-order', 'item-master', 'carry-forward', 'manual');
CREATE TYPE disposition AS ENUM (
  'Rejected', 'Hold', 'Repair', 'Used in another order', 'Accept with concession'
);
CREATE TYPE pt_consumable_kind AS ENUM ('Cleaner', 'Penetrant', 'Developer');
CREATE TYPE pt_verdict AS ENUM ('Accept', 'Reject / Repair');
CREATE TYPE image_driver AS ENUM ('local', 'azure-blob');
CREATE TYPE audit_action AS ENUM ('create', 'update', 'delete', 'restore', 'purge', 'acknowledge');

-- ---- Trigger functions -----------------------------------------------------

CREATE FUNCTION set_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END $$;

-- §10 — evidence is never destroyed. Removing a record means setting deleted_at.
CREATE FUNCTION forbid_hard_delete() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'Hard delete is not allowed on %. Set deleted_at instead.', TG_TABLE_NAME
    USING ERRCODE = 'restrict_violation';
END $$;

-- §11 — an audit entry is immutable except for being marked purged.
CREATE FUNCTION protect_audit_entry() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.at IS DISTINCT FROM OLD.at
     OR NEW.user_id IS DISTINCT FROM OLD.user_id
     OR NEW.user_name IS DISTINCT FROM OLD.user_name
     OR NEW.action IS DISTINCT FROM OLD.action
     OR NEW.entity IS DISTINCT FROM OLD.entity
     OR NEW.entity_id IS DISTINCT FROM OLD.entity_id
     OR NEW.field IS DISTINCT FROM OLD.field
     OR NEW.old_value IS DISTINCT FROM OLD.old_value
     OR NEW.new_value IS DISTINCT FROM OLD.new_value
     OR NEW.order_number IS DISTINCT FROM OLD.order_number
     OR NEW.item IS DISTINCT FROM OLD.item
     OR NEW.work_center_code IS DISTINCT FROM OLD.work_center_code
     OR NEW.session_id IS DISTINCT FROM OLD.session_id
     OR NEW.sample_id IS DISTINCT FROM OLD.sample_id
  THEN
    RAISE EXCEPTION 'Audit entries cannot be edited.' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END $$;

-- ---- Users & authentication ------------------------------------------------

CREATE TABLE users (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  email          text NOT NULL,
  name           text NOT NULL,
  role           user_role NOT NULL DEFAULT 'inspector',
  password_hash  text NOT NULL,
  is_active      boolean NOT NULL DEFAULT true,
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now(),
  last_login_at  timestamptz,
  CONSTRAINT users_email_format CHECK (email = lower(btrim(email)) AND position('@' IN email) > 1),
  CONSTRAINT users_name_not_blank CHECK (btrim(name) <> '')
);
CREATE UNIQUE INDEX users_email_key ON users (email);
CREATE TRIGGER users_updated_at BEFORE UPDATE ON users FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- One row per signed-in device. The refresh token itself is never stored,
-- only its hash; revoking the row signs that device out.
CREATE TABLE auth_sessions (
  id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id            uuid NOT NULL REFERENCES users (id),
  refresh_token_hash text NOT NULL UNIQUE,
  created_at         timestamptz NOT NULL DEFAULT now(),
  expires_at         timestamptz NOT NULL,
  last_used_at       timestamptz NOT NULL DEFAULT now(),
  revoked_at         timestamptz,
  user_agent         text,
  ip_address         text
);
CREATE INDEX auth_sessions_user_idx ON auth_sessions (user_id) WHERE revoked_at IS NULL;
CREATE INDEX auth_sessions_expires_idx ON auth_sessions (expires_at);

-- ---- Master data -----------------------------------------------------------

CREATE TABLE machines (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code           text NOT NULL,
  name           text NOT NULL,
  line           text NOT NULL DEFAULT '',
  display_name   text NOT NULL,
  machine_number text,
  factory        text,
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now(),
  deleted_at     timestamptz,
  deleted_by_id  uuid REFERENCES users (id),
  CONSTRAINT machines_code_not_blank CHECK (btrim(code) <> '')
);
CREATE UNIQUE INDEX machines_display_name_key ON machines (lower(display_name)) WHERE deleted_at IS NULL;
CREATE INDEX machines_code_idx ON machines (code) WHERE deleted_at IS NULL;
CREATE TRIGGER machines_updated_at BEFORE UPDATE ON machines FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER machines_no_delete BEFORE DELETE ON machines FOR EACH ROW EXECUTE FUNCTION forbid_hard_delete();

CREATE TABLE production_orders (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  order_number     text NOT NULL,
  item             text NOT NULL DEFAULT '',
  item_code        text NOT NULL DEFAULT '',
  work_center_code text NOT NULL DEFAULT '',
  machine_id       uuid REFERENCES machines (id),
  required_qty     numeric(14, 3) NOT NULL DEFAULT 0,
  finished_qty     numeric(14, 3) NOT NULL DEFAULT 0,
  drawing          text NOT NULL DEFAULT '',
  drawing_alt      text,
  issue            text,
  material         text NOT NULL DEFAULT '',
  expected_grade   text NOT NULL DEFAULT '',
  customer         text NOT NULL DEFAULT '',
  type             text NOT NULL DEFAULT '',
  colour           text NOT NULL DEFAULT '',
  order_date       timestamptz NOT NULL DEFAULT now(),
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  deleted_at       timestamptz,
  deleted_by_id    uuid REFERENCES users (id),
  CONSTRAINT production_orders_number_not_blank CHECK (btrim(order_number) <> ''),
  CONSTRAINT production_orders_qty_nonnegative CHECK (required_qty >= 0 AND finished_qty >= 0)
);
-- text_pattern_ops lets the same index serve uniqueness AND `LIKE 'prefix%'`.
CREATE UNIQUE INDEX production_orders_number_key ON production_orders (lower(order_number) text_pattern_ops);
CREATE INDEX production_orders_item_code_idx ON production_orders (lower(item_code) text_pattern_ops);
CREATE INDEX production_orders_work_center_idx ON production_orders (work_center_code);
CREATE TRIGGER production_orders_updated_at BEFORE UPDATE ON production_orders FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER production_orders_no_delete BEFORE DELETE ON production_orders FOR EACH ROW EXECUTE FUNCTION forbid_hard_delete();

CREATE TABLE coils (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  coil_number   text NOT NULL,
  grade         text,
  sm_type       text,
  supplier      text,
  thickness     numeric(10, 3),
  width         numeric(10, 3),
  yield         numeric(10, 3),
  notes         text,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  deleted_at    timestamptz,
  deleted_by_id uuid REFERENCES users (id),
  CONSTRAINT coils_number_not_blank CHECK (btrim(coil_number) <> '')
);
CREATE UNIQUE INDEX coils_number_key ON coils (lower(coil_number) text_pattern_ops);
CREATE INDEX coils_grade_idx ON coils (lower(grade) text_pattern_ops);
CREATE INDEX coils_supplier_idx ON coils (lower(supplier) text_pattern_ops);
CREATE TRIGGER coils_updated_at BEFORE UPDATE ON coils FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER coils_no_delete BEFORE DELETE ON coils FOR EACH ROW EXECUTE FUNCTION forbid_hard_delete();

CREATE TABLE item_dimension_order (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  item           text NOT NULL,
  dimension_name text NOT NULL,
  sequence       integer NOT NULL DEFAULT 1,
  nominal        numeric(14, 4),
  tol_plus       numeric(14, 4) NOT NULL DEFAULT 0,
  tol_minus      numeric(14, 4) NOT NULL DEFAULT 0,
  unit           text NOT NULL DEFAULT 'mm',
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now(),
  deleted_at     timestamptz,
  deleted_by_id  uuid REFERENCES users (id),
  CONSTRAINT item_dimension_order_not_blank CHECK (btrim(item) <> '' AND btrim(dimension_name) <> '')
);
CREATE UNIQUE INDEX item_dimension_order_key
  ON item_dimension_order (lower(item), lower(dimension_name)) WHERE deleted_at IS NULL;
CREATE INDEX item_dimension_order_item_idx ON item_dimension_order (item) WHERE deleted_at IS NULL;
CREATE TRIGGER item_dimension_order_updated_at BEFORE UPDATE ON item_dimension_order FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER item_dimension_order_no_delete BEFORE DELETE ON item_dimension_order FOR EACH ROW EXECUTE FUNCTION forbid_hard_delete();

CREATE TABLE item_dimension_master (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  item           text NOT NULL,
  dimension_name text NOT NULL,
  nominal        numeric(14, 4),
  tol_plus       numeric(14, 4) NOT NULL DEFAULT 0,
  tol_minus      numeric(14, 4) NOT NULL DEFAULT 0,
  unit           text NOT NULL DEFAULT 'mm',
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now(),
  deleted_at     timestamptz,
  deleted_by_id  uuid REFERENCES users (id),
  CONSTRAINT item_dimension_master_not_blank CHECK (btrim(item) <> '' AND btrim(dimension_name) <> '')
);
CREATE UNIQUE INDEX item_dimension_master_key
  ON item_dimension_master (lower(item), lower(dimension_name)) WHERE deleted_at IS NULL;
CREATE INDEX item_dimension_master_item_idx ON item_dimension_master (item) WHERE deleted_at IS NULL;
CREATE TRIGGER item_dimension_master_updated_at BEFORE UPDATE ON item_dimension_master FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER item_dimension_master_no_delete BEFORE DELETE ON item_dimension_master FOR EACH ROW EXECUTE FUNCTION forbid_hard_delete();

CREATE TABLE work_center_defects (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  work_center_code text NOT NULL,
  defect_name      text NOT NULL,
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  deleted_at       timestamptz,
  deleted_by_id    uuid REFERENCES users (id),
  CONSTRAINT work_center_defects_not_blank CHECK (btrim(work_center_code) <> '' AND btrim(defect_name) <> '')
);
CREATE UNIQUE INDEX work_center_defects_key
  ON work_center_defects (work_center_code, lower(defect_name)) WHERE deleted_at IS NULL;
CREATE TRIGGER work_center_defects_updated_at BEFORE UPDATE ON work_center_defects FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER work_center_defects_no_delete BEFORE DELETE ON work_center_defects FOR EACH ROW EXECUTE FUNCTION forbid_hard_delete();

CREATE TABLE grade_mappings (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  grade_a       text NOT NULL,
  grade_b       text NOT NULL,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  deleted_at    timestamptz,
  deleted_by_id uuid REFERENCES users (id),
  CONSTRAINT grade_mappings_not_blank CHECK (btrim(grade_a) <> '' AND btrim(grade_b) <> '')
);
CREATE TRIGGER grade_mappings_updated_at BEFORE UPDATE ON grade_mappings FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER grade_mappings_no_delete BEFORE DELETE ON grade_mappings FOR EACH ROW EXECUTE FUNCTION forbid_hard_delete();

CREATE TABLE pt_consumables (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  kind          pt_consumable_kind NOT NULL,
  product_name  text NOT NULL,
  lot_batch     text NOT NULL,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  deleted_at    timestamptz,
  deleted_by_id uuid REFERENCES users (id),
  CONSTRAINT pt_consumables_not_blank CHECK (btrim(product_name) <> '' AND btrim(lot_batch) <> '')
);
CREATE TRIGGER pt_consumables_updated_at BEFORE UPDATE ON pt_consumables FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER pt_consumables_no_delete BEFORE DELETE ON pt_consumables FOR EACH ROW EXECUTE FUNCTION forbid_hard_delete();

-- ---- Images ----------------------------------------------------------------
-- Created before anything that references them: bytes are stored first (§9.5),
-- the metadata row second, and only then may a record point at the image.

CREATE TABLE images (
  id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  storage_key        text NOT NULL UNIQUE,
  driver             image_driver NOT NULL,
  original_filename  text NOT NULL,
  mime_type          text NOT NULL,
  byte_size          integer NOT NULL CHECK (byte_size > 0),
  width              integer NOT NULL CHECK (width > 0),
  height             integer NOT NULL CHECK (height > 0),
  sha256             char(64) NOT NULL,
  uploaded_by_id     uuid NOT NULL REFERENCES users (id),
  uploaded_by_name   text NOT NULL,
  uploaded_at        timestamptz NOT NULL DEFAULT now(),
  thumbnail_data_url text,
  session_id         uuid,
  sample_id          uuid,
  order_id           uuid,
  deleted_at         timestamptz,
  deleted_by_id      uuid REFERENCES users (id)
);
CREATE INDEX images_session_idx ON images (session_id) WHERE session_id IS NOT NULL;
CREATE INDEX images_order_idx ON images (order_id) WHERE order_id IS NOT NULL;
CREATE TRIGGER images_no_delete BEFORE DELETE ON images FOR EACH ROW EXECUTE FUNCTION forbid_hard_delete();

CREATE TABLE item_reference_images (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  item          text NOT NULL,
  image_id      uuid NOT NULL REFERENCES images (id),
  caption       text,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  deleted_at    timestamptz,
  deleted_by_id uuid REFERENCES users (id),
  CONSTRAINT item_reference_images_not_blank CHECK (btrim(item) <> '')
);
CREATE INDEX item_reference_images_item_idx ON item_reference_images (item) WHERE deleted_at IS NULL;
CREATE TRIGGER item_reference_images_updated_at BEFORE UPDATE ON item_reference_images FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER item_reference_images_no_delete BEFORE DELETE ON item_reference_images FOR EACH ROW EXECUTE FUNCTION forbid_hard_delete();

-- ---- Inspection evidence ---------------------------------------------------

CREATE TABLE inspection_sessions (
  id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  seq                integer NOT NULL,
  order_id           uuid NOT NULL REFERENCES production_orders (id),
  work_center_code   text NOT NULL,
  inspector_id       uuid NOT NULL REFERENCES users (id),
  inspector_name     text NOT NULL,
  started_at         timestamptz NOT NULL DEFAULT now(),
  status             session_status NOT NULL DEFAULT 'Open',
  start_qty          numeric(14, 3),
  start_qty_by_id    uuid REFERENCES users (id),
  start_qty_by_name  text,
  start_qty_at       timestamptz,
  final_qty          numeric(14, 3),
  closed_at          timestamptz,
  closed_by_id       uuid REFERENCES users (id),
  version            integer NOT NULL DEFAULT 0,
  created_at         timestamptz NOT NULL DEFAULT now(),
  updated_at         timestamptz NOT NULL DEFAULT now(),
  deleted_at         timestamptz,
  deleted_by_id      uuid REFERENCES users (id),
  CONSTRAINT inspection_sessions_seq_positive CHECK (seq > 0),
  CONSTRAINT inspection_sessions_closed_consistent CHECK (
    (status = 'Open' AND closed_at IS NULL) OR (status = 'Closed' AND closed_at IS NOT NULL)
  ),
  UNIQUE (order_id, seq)
);
CREATE INDEX inspection_sessions_open_idx ON inspection_sessions (started_at DESC) WHERE status = 'Open' AND deleted_at IS NULL;
CREATE INDEX inspection_sessions_recent_idx ON inspection_sessions (started_at DESC) WHERE deleted_at IS NULL;
CREATE INDEX inspection_sessions_order_idx ON inspection_sessions (order_id);
CREATE TRIGGER inspection_sessions_updated_at BEFORE UPDATE ON inspection_sessions FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER inspection_sessions_no_delete BEFORE DELETE ON inspection_sessions FOR EACH ROW EXECUTE FUNCTION forbid_hard_delete();

CREATE TABLE inspection_samples (
  id                        uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  session_id                uuid NOT NULL REFERENCES inspection_sessions (id),
  order_id                  uuid NOT NULL REFERENCES production_orders (id),
  index                     integer NOT NULL CHECK (index > 0),
  shift                     shift_letter NOT NULL,
  created_at                timestamptz NOT NULL DEFAULT now(),
  inspector_id              uuid NOT NULL REFERENCES users (id),
  inspector_name            text NOT NULL,
  drawing                   text NOT NULL,
  drawing_alt               text,
  issue                     text,
  sample_qty                numeric(14, 3) NOT NULL CHECK (sample_qty > 0),
  -- §8.4 — a grade mismatch that was acknowledged is itself evidence.
  grade_ack_by_id           uuid REFERENCES users (id),
  grade_ack_by_name         text,
  grade_ack_at              timestamptz,
  grade_ack_coil_numbers    text[],
  grade_ack_expected_grade  text,
  grade_ack_found_grades    text[],
  -- §9.3 — the client's idempotency key. A retry lands on this row.
  submission_id             uuid NOT NULL UNIQUE,
  version                   integer NOT NULL DEFAULT 0,
  updated_at                timestamptz NOT NULL DEFAULT now(),
  deleted_at                timestamptz,
  deleted_by_id             uuid REFERENCES users (id),
  UNIQUE (session_id, index)
);
CREATE INDEX inspection_samples_order_idx ON inspection_samples (order_id, created_at DESC);
CREATE TRIGGER inspection_samples_updated_at BEFORE UPDATE ON inspection_samples FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER inspection_samples_no_delete BEFORE DELETE ON inspection_samples FOR EACH ROW EXECUTE FUNCTION forbid_hard_delete();

CREATE TABLE dimension_results (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  sample_id     uuid NOT NULL REFERENCES inspection_samples (id),
  name          text NOT NULL,
  sequence      integer NOT NULL DEFAULT 1,
  nominal       numeric(14, 4),
  tol_plus      numeric(14, 4),
  tol_minus     numeric(14, 4),
  actual        numeric(14, 4),
  unit          text NOT NULL DEFAULT 'mm',
  status        dimension_status NOT NULL,
  source        dimension_source NOT NULL,
  version       integer NOT NULL DEFAULT 0,
  updated_at    timestamptz NOT NULL DEFAULT now(),
  deleted_at    timestamptz,
  deleted_by_id uuid REFERENCES users (id)
);
CREATE INDEX dimension_results_sample_idx ON dimension_results (sample_id, sequence);
CREATE TRIGGER dimension_results_updated_at BEFORE UPDATE ON dimension_results FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER dimension_results_no_delete BEFORE DELETE ON dimension_results FOR EACH ROW EXECUTE FUNCTION forbid_hard_delete();

CREATE TABLE defect_results (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  sample_id     uuid NOT NULL REFERENCES inspection_samples (id),
  defect_name   text NOT NULL,
  qty           numeric(14, 3) NOT NULL CHECK (qty > 0),
  -- §8.5 — no defect exists without a disposition.
  disposition   disposition NOT NULL,
  notes         text,
  version       integer NOT NULL DEFAULT 0,
  updated_at    timestamptz NOT NULL DEFAULT now(),
  deleted_at    timestamptz,
  deleted_by_id uuid REFERENCES users (id)
);
CREATE INDEX defect_results_sample_idx ON defect_results (sample_id);
CREATE INDEX defect_results_disposition_idx ON defect_results (disposition) WHERE deleted_at IS NULL;
CREATE TRIGGER defect_results_updated_at BEFORE UPDATE ON defect_results FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER defect_results_no_delete BEFORE DELETE ON defect_results FOR EACH ROW EXECUTE FUNCTION forbid_hard_delete();

CREATE TABLE defect_images (
  defect_id uuid NOT NULL REFERENCES defect_results (id),
  image_id  uuid NOT NULL REFERENCES images (id),
  position  integer NOT NULL,
  PRIMARY KEY (defect_id, image_id)
);
CREATE TRIGGER defect_images_no_delete BEFORE DELETE ON defect_images FOR EACH ROW EXECUTE FUNCTION forbid_hard_delete();

CREATE TABLE sample_coils (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  sample_id     uuid NOT NULL REFERENCES inspection_samples (id),
  coil_number   text NOT NULL,
  grade         text,
  sm_type       text,
  supplier      text,
  thickness     numeric(10, 3),
  width         numeric(10, 3),
  yield         numeric(10, 3),
  notes         text,
  deleted_at    timestamptz,
  deleted_by_id uuid REFERENCES users (id),
  CONSTRAINT sample_coils_number_not_blank CHECK (btrim(coil_number) <> '')
);
CREATE INDEX sample_coils_sample_idx ON sample_coils (sample_id);
CREATE INDEX sample_coils_number_idx ON sample_coils (lower(coil_number));
CREATE TRIGGER sample_coils_no_delete BEFORE DELETE ON sample_coils FOR EACH ROW EXECUTE FUNCTION forbid_hard_delete();

CREATE TABLE paint_samples (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  sample_id     uuid NOT NULL UNIQUE REFERENCES inspection_samples (id),
  notes         text,
  deleted_at    timestamptz,
  deleted_by_id uuid REFERENCES users (id)
);
CREATE TRIGGER paint_samples_no_delete BEFORE DELETE ON paint_samples FOR EACH ROW EXECUTE FUNCTION forbid_hard_delete();

CREATE TABLE paint_sample_images (
  paint_sample_id uuid NOT NULL REFERENCES paint_samples (id),
  image_id        uuid NOT NULL REFERENCES images (id),
  position        integer NOT NULL,
  PRIMARY KEY (paint_sample_id, image_id)
);
CREATE TRIGGER paint_sample_images_no_delete BEFORE DELETE ON paint_sample_images FOR EACH ROW EXECUTE FUNCTION forbid_hard_delete();

CREATE TABLE pt_records (
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  sample_id           uuid NOT NULL UNIQUE REFERENCES inspection_samples (id),
  -- §5.6 — the test frequency must be greater than 5%.
  test_frequency_pct  numeric(6, 2) NOT NULL CHECK (test_frequency_pct > 5),
  cleaner_lot         text NOT NULL,
  penetrant_lot       text NOT NULL,
  developer_lot       text NOT NULL,
  sample_size         text,
  tested_weld_length  text,
  indication_type     text,
  indication_size     text,
  welding_wire_batch  text,
  accept_or_repair    pt_verdict,
  final_result        text,
  notes               text,
  deleted_at          timestamptz,
  deleted_by_id       uuid REFERENCES users (id),
  CONSTRAINT pt_records_lots_not_blank CHECK (
    btrim(cleaner_lot) <> '' AND btrim(penetrant_lot) <> '' AND btrim(developer_lot) <> ''
  )
);
CREATE TRIGGER pt_records_no_delete BEFORE DELETE ON pt_records FOR EACH ROW EXECUTE FUNCTION forbid_hard_delete();

CREATE TABLE pt_record_images (
  pt_record_id uuid NOT NULL REFERENCES pt_records (id),
  image_id     uuid NOT NULL REFERENCES images (id),
  position     integer NOT NULL,
  PRIMARY KEY (pt_record_id, image_id)
);
CREATE TRIGGER pt_record_images_no_delete BEFORE DELETE ON pt_record_images FOR EACH ROW EXECUTE FUNCTION forbid_hard_delete();

CREATE TABLE pdi_documents (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  order_id        uuid NOT NULL REFERENCES production_orders (id),
  notes           text,
  created_at      timestamptz NOT NULL DEFAULT now(),
  created_by_id   uuid NOT NULL REFERENCES users (id),
  created_by_name text NOT NULL,
  deleted_at      timestamptz,
  deleted_by_id   uuid REFERENCES users (id)
);
CREATE INDEX pdi_documents_recent_idx ON pdi_documents (created_at DESC) WHERE deleted_at IS NULL;
CREATE INDEX pdi_documents_order_idx ON pdi_documents (order_id);
CREATE TRIGGER pdi_documents_no_delete BEFORE DELETE ON pdi_documents FOR EACH ROW EXECUTE FUNCTION forbid_hard_delete();

CREATE TABLE pdi_images (
  pdi_id   uuid NOT NULL REFERENCES pdi_documents (id),
  image_id uuid NOT NULL REFERENCES images (id),
  position integer NOT NULL,
  PRIMARY KEY (pdi_id, image_id)
);
CREATE TRIGGER pdi_images_no_delete BEFORE DELETE ON pdi_images FOR EACH ROW EXECUTE FUNCTION forbid_hard_delete();

-- ---- Audit trail -----------------------------------------------------------

CREATE TABLE audit_log (
  id               bigserial PRIMARY KEY,
  at               timestamptz NOT NULL DEFAULT now(),
  user_id          uuid NOT NULL REFERENCES users (id),
  user_name        text NOT NULL,
  action           audit_action NOT NULL,
  entity           text NOT NULL,
  entity_id        text NOT NULL,
  field            text,
  old_value        text,
  new_value        text,
  order_number     text,
  item             text,
  work_center_code text,
  session_id       uuid,
  sample_id        uuid,
  -- A "purge" is a soft delete like everything else, and is itself audited.
  deleted_at       timestamptz,
  deleted_by_id    uuid REFERENCES users (id),
  deleted_by_name  text
);
CREATE INDEX audit_log_at_idx ON audit_log (at DESC) WHERE deleted_at IS NULL;
CREATE INDEX audit_log_action_idx ON audit_log (action) WHERE deleted_at IS NULL;
CREATE INDEX audit_log_entity_idx ON audit_log (entity, entity_id);
CREATE TRIGGER audit_log_no_delete BEFORE DELETE ON audit_log FOR EACH ROW EXECUTE FUNCTION forbid_hard_delete();
CREATE TRIGGER audit_log_immutable BEFORE UPDATE ON audit_log FOR EACH ROW EXECUTE FUNCTION protect_audit_entry();
